"""PeerSim bridge: reads event schedule files generated by PeerSim and
converts them into HEAL failure_schedule dicts for run_simulation."""
import json
import os
import random
from typing import Dict, Callable, List, Tuple

import networkx as nx

from src.simulation.heal_node import HealClient, HealHub


EventFile = str
FailureFn = Callable[
    [List[HealClient], List[HealHub], List[int], nx.Graph],
    Tuple[List[HealClient], List[HealHub], List[int], nx.Graph],
]


def load_peersim_events(event_file: str) -> Dict[int, list]:
    """
    Read a PeerSim event JSON:
    {
      "events": [
        {"cycle": 100, "type": "crash", "node_ids": [5, 12, 33]},
        {"cycle": 200, "type": "join",  "node_ids": [5]},
        ...
      ]
    }
    Returns dict: {cycle: [event, ...]}
    """
    with open(event_file) as f:
        data = json.load(f)

    schedule: Dict[int, list] = {}
    for ev in data.get("events", []):
        c = ev["cycle"]
        schedule.setdefault(c, []).append(ev)
    return schedule


def peersim_to_failure_schedule(
    event_file: str,
    model_factory,
    node_loaders: dict,
    lr: float = 0.01,
    device: str = "cpu",
) -> Dict[int, FailureFn]:
    """
    Convert a PeerSim event file to a failure_schedule dict for run_simulation.

    model_factory: callable () -> nn.Module (used to create rejoining nodes)
    """
    raw = load_peersim_events(event_file)
    schedule: Dict[int, FailureFn] = {}

    for cycle, events in raw.items():
        crash_ids = {
            nid
            for ev in events if ev["type"] == "crash"
            for nid in ev["node_ids"]
        }
        hub_crash_ids = {
            nid
            for ev in events if ev["type"] == "hub_crash"
            for nid in ev["node_ids"]
        }
        join_ids = {
            nid
            for ev in events if ev["type"] == "join"
            for nid in ev["node_ids"]
        }
        all_crash = crash_ids | hub_crash_ids

        def make_fn(cycle_crash, cycle_hub_crash, cycle_join, c=cycle):
            def fn(clients, hubs, hub_ids, G):
                new_clients = [x for x in clients if x.id not in cycle_crash]
                new_hubs    = [x for x in hubs    if x.id not in cycle_crash
                               and x.id not in cycle_hub_crash]
                new_hub_ids = [i for i in hub_ids  if i not in cycle_crash
                               and i not in cycle_hub_crash]

                # Hub re-election if hubs crashed
                if cycle_hub_crash:
                    n_elect = len([h for h in hubs if h.id in cycle_hub_crash])
                    for nc in new_clients[:n_elect]:
                        new_hub = HealHub(
                            nc.id, nc.model, nc.data_loader,
                            lr=nc.optimizer.param_groups[0]["lr"],
                            device=nc.device,
                        )
                        new_hubs.append(new_hub)
                        new_hub_ids.append(nc.id)
                    new_clients = new_clients[n_elect:]

                # Rejoin nodes with fresh models
                for nid in cycle_join:
                    if nid in node_loaders:
                        rejoiner = HealClient(
                            nid, model_factory(), node_loaders[nid],
                            lr=lr, device=device,
                        )
                        new_clients.append(rejoiner)

                new_G = G.copy()
                for nid in cycle_crash | cycle_hub_crash:
                    if nid in new_G:
                        new_G.remove_node(nid)
                for nid in cycle_join:
                    if nid not in new_G:
                        new_G.add_node(nid)

                return new_clients, new_hubs, new_hub_ids, new_G
            return fn

        schedule[cycle] = make_fn(crash_ids, hub_crash_ids, join_ids)

    return schedule


def generate_e2_events(n_nodes: int, crash_frac: float = 0.2, seed: int = 42) -> dict:
    """Generate E2-style events (20% random crash at cycle 100) without PeerSim."""
    rng = random.Random(seed)
    n_crash = max(1, int(crash_frac * n_nodes))
    node_ids = rng.sample(range(n_nodes), n_crash)
    return {
        "events": [{"cycle": 100, "type": "crash", "node_ids": node_ids}]
    }


def generate_e3_events(hub_ids: list) -> dict:
    """Generate E3-style events (all hubs crash at cycle 100) without PeerSim."""
    return {
        "events": [{"cycle": 100, "type": "hub_crash", "node_ids": list(hub_ids)}]
    }


def generate_e4_events(n_nodes: int, churn_frac: float = 0.1, seed: int = 42) -> dict:
    """Generate E4-style churn events (10% every 50 cycles) without PeerSim."""
    rng = random.Random(seed)
    n_churn = max(1, int(churn_frac * n_nodes))
    events = []
    for cycle in range(50, 1001, 50):
        crash_ids = rng.sample(range(n_nodes), n_churn)
        events.append({"cycle": cycle, "type": "crash", "node_ids": crash_ids})
        # Nodes rejoin 50 cycles later
        events.append({"cycle": cycle + 50, "type": "join", "node_ids": crash_ids})
    return {"events": events}


def save_events(events: dict, path: str) -> None:
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    with open(path, "w") as f:
        json.dump(events, f, indent=2)
